  // particle
  int idx = type.transport_index();
  if (idx == C_NONE) {
    return false;
  }
  if (E < settings::energy_cutoff[idx]) {
    return false;
  }

  // Increment number of secondaries created (for ParticleProductionFilter)
  n_secondaries()++;

  SourceSite bank;
  bank.particle = type;
  bank.wgt = wgt;
  bank.r = r();
  bank.u = u;
  bank.E = settings::run_CE ? E : g();
  bank.time = time();
  bank_second_E() += bank.E;
  bank.parent_id = current_work();
  if (settings::use_shared_secondary_bank) {
    bank.progeny_id = n_progeny()++;
  }
  bank.wgt_born = wgt_born();
  bank.wgt_ww_born = wgt_ww_born();
  bank.n_split = n_split();

  local_secondary_bank().emplace_back(bank);
  return true;
}

void Particle::split(double wgt)
{
  SourceSite bank;
  bank.particle = type();
  bank.wgt = wgt;
  bank.r = r();
  bank.u = u();
  bank.E = settings::run_CE ? E() : g();
  bank.time = time();

  // Convert signed index to a signed surface ID
  if (surface() == SURFACE_NONE) {
    bank.surf_id = SURFACE_NONE;
  } else {
    int surf_id = model::surfaces[surface_index()]->id_;
    bank.surf_id = (surface() > 0) ? surf_id : -surf_id;
  }

  bank.wgt_born = wgt_born();
  bank.wgt_ww_born = wgt_ww_born();
  bank.n_split = n_split();
  bank.parent_id = current_work();
  if (settings::use_shared_secondary_bank) {
    bank.progeny_id = n_progeny()++;
  }

  local_secondary_bank().emplace_back(bank);
}

void Particle::from_source(const SourceSite* src)
{
  // Reset some attributes
  clear();
  surface() = SURFACE_NONE;
  cell_born() = C_NONE;
  material() = C_NONE;
  n_collision() = 0;
  fission() = false;
  zero_flux_derivs();
  lifetime() = 0.0;
#ifdef OPENMC_DAGMC_ENABLED
  history().reset();
#endif

  // Copy attributes from source bank site
  type() = src->particle;
  wgt() = src->wgt;
  wgt_last() = src->wgt;
  r() = src->r;
  u() = src->u;
  r_born() = src->r;
  r_last_current() = src->r;
  r_last() = src->r;
  u_last() = src->u;
  if (settings::run_CE) {
    E() = src->E;
    g() = 0;
  } else {
    g() = static_cast<int>(src->E);
    g_last() = static_cast<int>(src->E);
    E() = data::mg.energy_bin_avg_[g()];
  }
  E_last() = E();
  time() = src->time;
  time_last() = src->time;
  parent_nuclide() = src->parent_nuclide;
  delayed_group() = src->delayed_group;

  // Convert signed surface ID to signed index
  if (src->surf_id != SURFACE_NONE) {
    int index_plus_one = model::surface_map[std::abs(src->surf_id)] + 1;
    surface() = (src->surf_id > 0) ? index_plus_one : -index_plus_one;
  }

  wgt_born() = src->wgt_born;
  wgt_ww_born() = src->wgt_ww_born;
  n_split() = src->n_split;
}

void Particle::event_calculate_xs()
{
  // Set the random number stream
  stream() = STREAM_TRACKING;

  // Store pre-collision particle properties
  wgt_last() = wgt();
  E_last() = E();
  u_last() = u();
  r_last() = r();
  time_last() = time();

  // Reset event variables
  event() = TallyEvent::KILL;
  event_nuclide() = NUCLIDE_NONE;
  event_mt() = REACTION_NONE;

  // If the cell hasn't been determined based on the particle's location,
  // initiate a search for the current cell. This generally happens at the
  // beginning of the history and again for any secondary particles
  if (lowest_coord().cell() == C_NONE) {
    if (!exhaustive_find_cell(*this)) {
      mark_as_lost(
        "Could not find the cell containing particle " + std::to_string(id()));
      return;
    }

    // Set birth cell attribute
    if (cell_born() == C_NONE)
      cell_born() = lowest_coord().cell();

    // Initialize last cells from current cell
    for (int j = 0; j < n_coord(); ++j) {
      cell_last(j) = coord(j).cell();
    }
    n_coord_last() = n_coord();
  }

  // Write particle track.
  if (write_track())
    write_particle_track(*this);

  if (settings::check_overlaps)
    check_cell_overlap(*this);

  // Calculate microscopic and macroscopic cross sections
  if (material() != MATERIAL_VOID) {
    if (settings::run_CE) {
      if (material() != material_last() || sqrtkT() != sqrtkT_last() ||
          density_mult() != density_mult_last()) {
        // If the material is the same as the last material and the
        // temperature hasn't changed, we don't need to lookup cross
        // sections again.
        model::materials[material()]->calculate_xs(*this);
      }
    } else {
      // Get the MG data; unlike the CE case above, we have to re-calculate
      // cross sections for every collision since the cross sections may
      // be angle-dependent
      data::mg.macro_xs_[material()].calculate_xs(*this);

      // Update the particle's group while we know we are multi-group
      g_last() = g();
    }
  } else {
    macro_xs().total = 0.0;
    macro_xs().absorption = 0.0;
    macro_xs().fission = 0.0;
    macro_xs().nu_fission = 0.0;
  }
}

void Particle::event_advance()
{
  // Find the distance to the nearest boundary
  boundary() = distance_to_boundary(*this);

  // Sample a distance to collision
  if (type() == ParticleType::electron() ||
      type() == ParticleType::positron()) {
    collision_distance() = material() == MATERIAL_VOID ? INFINITY : 0.0;
  } else if (macro_xs().total == 0.0) {
    collision_distance() = INFINITY;
  } else {
    collision_distance() = -std::log(prn(current_seed())) / macro_xs().total;
  }

  double speed = this->speed();
  double time_cutoff = settings::time_cutoff[type().transport_index()];
  double distance_cutoff =
    (time_cutoff < INFTY) ? (time_cutoff - time()) * speed : INFTY;

  // Select smaller of the three distances
  double distance =
    std::min({boundary().distance(), collision_distance(), distance_cutoff});

  // Advance particle in space and time
  this->move_distance(distance);
  double dt = distance / speed;
  this->time() += dt;
  this->lifetime() += dt;

  // Score timed track-length tallies
  if (!model::active_timed_tracklength_tallies.empty()) {
    score_timed_tracklength_tally(*this, distance);
  }

  // Score track-length tallies
  if (!model::active_tracklength_tallies.empty()) {
    score_tracklength_tally(*this, distance);
  }

  // Score track-length estimate of k-eff
  if (settings::run_mode == RunMode::EIGENVALUE && type().is_neutron()) {
    keff_tally_tracklength() += wgt() * distance * macro_xs().nu_fission;
  }

  // Score flux derivative accumulators for differential tallies.
  if (!model::active_tallies.empty()) {
    score_track_derivative(*this, distance);
  }

  // Set particle weight to zero if it hit the time boundary
  if (distance == distance_cutoff) {
    wgt() = 0.0;
  }
}

void Particle::event_cross_surface()
{
  // Saving previous cell data
  for (int j = 0; j < n_coord(); ++j) {
    cell_last(j) = coord(j).cell();
  }
  n_coord_last() = n_coord();

  // Set surface that particle is on and adjust coordinate levels
  surface() = boundary().surface();
  n_coord() = boundary().coord_level();

  if (boundary().lattice_translation()[0] != 0 ||
      boundary().lattice_translation()[1] != 0 ||
      boundary().lattice_translation()[2] != 0) {
    // Particle crosses lattice boundary

    bool verbose = settings::verbosity >= 10 || trace();
    cross_lattice(*this, boundary(), verbose);
    event() = TallyEvent::LATTICE;

    // Score cell to cell partial currents
    if (!model::active_surface_tallies.empty()) {
      auto& lat {*model::lattices[lowest_coord().lattice()]};
      bool is_valid;
      Direction normal =
        lat.get_normal(boundary().lattice_translation(), is_valid);
      if (is_valid) {
        normal /= normal.norm();
        score_surface_tally(*this, model::active_surface_tallies, normal);
      }
    }

  } else {

    const auto& surf {*model::surfaces[surface_index()].get()};

    // Particle crosses surface
    // If BC, add particle to surface source before crossing surface
    if (surf.surf_source_ && surf.bc_) {
      add_surf_source_to_bank(*this, surf);
    }
    this->cross_surface(surf);
    // If no BC, add particle to surface source after crossing surface
    if (surf.surf_source_ && !surf.bc_) {
      add_surf_source_to_bank(*this, surf);
    }
    if (settings::weight_window_checkpoint_surface) {
      apply_weight_windows(*this);
    }
    event() = TallyEvent::SURFACE;

    // Score cell to cell partial currents
    if (!model::active_surface_tallies.empty()) {
      Direction normal = surf.normal(r());
      normal /= normal.norm();
      score_surface_tally(*this, model::active_surface_tallies, normal);
    }
  }
}

void Particle::event_collide()
{

  // Score collision estimate of keff
  if (settings::run_mode == RunMode::EIGENVALUE && type().is_neutron()) {
    keff_tally_collision() += wgt() * macro_xs().nu_fission / macro_xs().total;
  }

  // Score surface current tallies -- this has to be done before the collision
  // since the direction of the particle will change and we need to use the
  // pre-collision direction to figure out what mesh surfaces were crossed

  if (!model::active_meshsurf_tallies.empty())
    score_meshsurface_tally(*this, model::active_meshsurf_tallies);

  // Clear surface component
  surface() = SURFACE_NONE;

  if (settings::run_CE) {
    collision(*this);
  } else {
    collision_mg(*this);
  }

  // Collision track feature to recording particle interaction
  if (settings::collision_track) {
    collision_track_record(*this);
  }

  // Score collision estimator tallies -- this is done after a collision
  // has occurred rather than before because we need information on the
  // outgoing energy for any tallies with an outgoing energy filter
  if (!model::active_collision_tallies.empty())
    score_collision_tally(*this);
  if (!model::active_analog_tallies.empty()) {
    if (settings::run_CE) {
      score_analog_tally_ce(*this);
    } else {
      score_analog_tally_mg(*this);
    }
  }

  if (!model::active_pulse_height_tallies.empty() && type().is_photon()) {
    pht_collision_energy();
  }

  // Reset banked weight during collision
  n_bank() = 0;
  bank_second_E() = 0.0;
  wgt_bank() = 0.0;

  // Clear number of secondaries in this collision. This is
  // distinct from the number of created neutrons n_bank() above!
  n_secondaries() = 0;

  zero_delayed_bank();

  // Reset fission logical
  fission() = false;

  // Save coordinates for tallying purposes
  r_last_current() = r();

  // Set last material to none since cross sections will need to be
  // re-evaluated
  material_last() = C_NONE;

  // Set all directions to base level -- right now, after a collision, only
  // the base level directions are changed
  for (int j = 0; j < n_coord() - 1; ++j) {
    if (coord(j + 1).rotated()) {
      // If next level is rotated, apply rotation matrix
      const auto& m {model::cells[coord(j).cell()]->rotation_};
      const auto& u {coord(j).u()};
      coord(j + 1).u() = u.rotate(m);
    } else {
      // Otherwise, copy this level's direction
      coord(j + 1).u() = coord(j).u();
    }
  }

  // Score flux derivative accumulators for differential tallies.
  if (!model::active_tallies.empty())
    score_collision_derivative(*this);

#ifdef OPENMC_DAGMC_ENABLED
  history().reset();
#endif
}

